sql.if:
AND (
    1 = 0
    
        OR ${params.dsAlias}.dept_id = #{params.dsDeptId}
    
    
        OR ${params.dsAlias}.dept_id = #{params.dsDeptId}
        OR ${params.dsAlias}.dept_id IN (
            SELECT d.id FROM sys_dept d
            WHERE find_in_set(#{params.dsDeptId}, d.ancestors)
        )
    
    
        OR ${params.dsAlias}.create_user = #{params.dsUserId}
        
            OR ${params.dsAlias}.engineer_id = #{params.dsUserId}
        
    
    
        OR ${params.dsAlias}.dept_id IN (
            SELECT rd.dept_id FROM sys_role_dept rd
            WHERE rd.role_id IN
            
                #{rid}
            
        )
    
)
